     5→using Nethermind.Abi;
     6→using Nethermind.Blockchain;
     7→using Nethermind.Blockchain.Tracing;
     8→using Nethermind.Consensus.Messages;
     9→using Nethermind.Core;
    10→using Nethermind.Core.Collections;
    11→using Nethermind.Core.ExecutionRequest;
    12→using Nethermind.Core.Specs;
    13→using Nethermind.Crypto;
    14→using Nethermind.Evm;
    15→using Nethermind.Evm.State;
    16→using Nethermind.Evm.TransactionProcessing;
    17→using Nethermind.Int256;
    18→using System;
    19→using System.Linq;
    20→
    21→namespace Nethermind.Consensus.ExecutionRequests;
    22→
    23→public class ExecutionRequestsProcessor : IExecutionRequestsProcessor
    24→{
    25→    public static readonly AbiSignature DepositEventAbi = new("DepositEvent", AbiType.DynamicBytes, AbiType.DynamicBytes, AbiType.DynamicBytes, AbiType.DynamicBytes, AbiType.DynamicBytes);
    26→    private readonly AbiEncoder _abiEncoder = AbiEncoder.Instance;
    27→
    28→    private const long GasLimit = 30_000_000L;
    29→
    30→    private readonly ITransactionProcessor _transactionProcessor;
    31→
    32→    private readonly SystemCall _withdrawalTransaction = new()
    33→    {
    34→        Value = UInt256.Zero,
    35→        Data = Array.Empty<byte>(),
    36→        To = Eip7002Constants.WithdrawalRequestPredeployAddress,
    37→        SenderAddress = Address.SystemUser,
    38→        GasLimit = GasLimit,
    39→        GasPrice = UInt256.Zero,
    40→    };
    41→
    42→    private readonly SystemCall _consolidationTransaction = new()
    43→    {
    44→        Value = UInt256.Zero,
    45→        Data = Array.Empty<byte>(),
    46→        To = Eip7251Constants.ConsolidationRequestPredeployAddress,
    47→        SenderAddress = Address.SystemUser,
    48→        GasLimit = GasLimit,
    49→        GasPrice = UInt256.Zero,
    50→    };
    51→
    52→    public ExecutionRequestsProcessor(ITransactionProcessor transactionProcessor)
    53→    {
    54→        _transactionProcessor = transactionProcessor;
    55→        _withdrawalTransaction.Hash = _withdrawalTransaction.CalculateHash();
    56→        _consolidationTransaction.Hash = _consolidationTransaction.CalculateHash();
    57→    }
    58→
    59→    public void ProcessExecutionRequests(Block block, IWorldState state, TxReceipt[] receipts, IReleaseSpec spec)
    60→    {
    61→        if (!spec.RequestsEnabled || block.IsGenesis)
    62→            return;
    63→
    64→        using ArrayPoolList<byte[]> requests = new(3);
    65→
    66→        ProcessDeposits(block, receipts, spec, requests);
    67→
    68→        if (spec.WithdrawalRequestsEnabled)
    69→        {
    70→            ReadRequests(block, state, spec.Eip7002ContractAddress, requests, _withdrawalTransaction, ExecutionRequestType.WithdrawalRequest,
    71→                BlockErrorMessages.WithdrawalsContractEmpty, BlockErrorMessages.WithdrawalsContractFailed);
    72→        }
    73→
    74→        if (spec.ConsolidationRequestsEnabled)
    75→        {
    76→            ReadRequests(block, state, spec.Eip7251ContractAddress, requests, _consolidationTransaction, ExecutionRequestType.ConsolidationRequest,
    77→                BlockErrorMessages.ConsolidationsContractEmpty, BlockErrorMessages.ConsolidationsContractFailed);
    78→        }
    79→
    80→        block.ExecutionRequests = [.. requests];
    81→        block.Header.RequestsHash = ExecutionRequestExtensions.CalculateHashFromFlatEncodedRequests(block.ExecutionRequests);
    82→    }
    83→
    84→    private void ProcessDeposits(Block block, TxReceipt[] receipts, IReleaseSpec spec, ArrayPoolList<byte[]> requests)
    85→    {
    86→        if (!spec.DepositsEnabled)
    87→            return;
    88→
    89→        using ArrayPoolList<byte> depositRequests = new(receipts.Length * 2 + 1)
    90→        {
    91→            (byte)ExecutionRequestType.Deposit
    92→        };
    93→
    94→        for (int i = 0; i < receipts.Length; i++)
    95→        {
    96→            LogEntry[]? logEntries = receipts[i].Logs;
    97→            if (logEntries is not null)
    98→            {
    99→                for (var j = 0; j < logEntries.Length; j++)
   100→                {
   101→                    LogEntry log = logEntries[j];
   102→                    if (log.Address == spec.DepositContractAddress && log.Topics.Length >= 1 && log.Topics[0] == DepositEventAbi.Hash)
   103→                    {
   104→                        Span<byte> depositRequestBuffer = new byte[ExecutionRequestExtensions.DepositRequestsBytesSize];
   105→                        DecodeDepositRequest(block, log, depositRequestBuffer);
   106→                        depositRequests.AddRange(depositRequestBuffer.ToArray());
   107→                    }
   108→                }
   109→            }
   110→        }
   111→
   112→        if (depositRequests.Count > 1)
   113→            requests.Add(depositRequests.ToArray());
   114→    }
   115→
   116→    private void DecodeDepositRequest(Block block, LogEntry log, Span<byte> buffer)
   117→    {
   118→        object[] result = null;
   119→        try
   120→        {
   121→            result = _abiEncoder.Decode(AbiEncodingStyle.None, DepositEventAbi, log.Data);
   122→            ValidateLayout(result, block);
   123→        }
   124→        catch (Exception e) when (e is AbiException or OverflowException)
   125→        {
   126→            throw new InvalidBlockException(block, BlockErrorMessages.InvalidDepositEventLayout(e.Message));
   127→        }
   128→
   129→        int offset = 0;
   130→
   131→        foreach (var item in result)
   132→        {
   133→            if (item is byte[] byteArray)
   134→            {
   135→                byteArray.CopyTo(buffer.Slice(offset, byteArray.Length));
   136→                offset += byteArray.Length;
   137→            }
   138→        }
   139→    }
   140→
   141→    private static void ValidateLayout(object[] result, Block block)
   142→    {
   143→        Validate(block, result[0], "pubkey", ExecutionRequestExtensions.PublicKeySize);
   144→        Validate(block, result[1], "withdrawalCredentials", ExecutionRequestExtensions.WithdrawalCredentialsSize);
   145→        Validate(block, result[2], "amount", ExecutionRequestExtensions.AmountSize);
   146→        Validate(block, result[3], "signature", ExecutionRequestExtensions.SignatureSize);
   147→        Validate(block, result[4], "index", ExecutionRequestExtensions.IndexSize);
   148→
   149→        static void Validate(Block block, object obj, string name, int expectedSize)
   150→        {
   151→            if (obj is not byte[] byteArray)
   152→            {
   153→                throw new InvalidBlockException(block, BlockErrorMessages.InvalidDepositEventLayout($"Decoded ABI result contains {name} as non-byte array element."));
   154→            }
   155→
   156→            if (byteArray.Length != expectedSize)
   157→            {
   158→                throw new InvalidBlockException(block, BlockErrorMessages.InvalidDepositEventLayout($"Decoded ABI result contains invalid {name} element, size does not match, expected {expectedSize}, got {byteArray.Length}."));
   159→            }
   160→        }
   161→    }
   162→
   163→    private void ReadRequests(Block block, IWorldState state, Address contractAddress, ArrayPoolList<byte[]> requests,
   164→        Transaction systemTx, ExecutionRequestType type, string contractEmptyError, string contractFailedError)
   165→    {
   166→        if (!state.HasCode(contractAddress))
   167→        {
   168→            throw new InvalidBlockException(block, contractEmptyError);
   169→        }
   170→
   171→        CallOutputTracer tracer = new();
   172→
   173→        _transactionProcessor.Execute(systemTx, tracer);
   174→
   175→        if (tracer.StatusCode == StatusCode.Failure)
